using System;

namespace Framework.Parameters
{
    /// <summary>
    /// パラメーターに適用する単一の補正情報を保持する。
    /// </summary>
    /// <remarks>
    /// 補正情報は生成後に変更できない。
    /// 補正値の変更は新しい補正情報への置き換えによって行う。
    /// 補正の適用、解除、有効時間は外部の管理クラスが担当する。
    /// </remarks>
    public sealed class ParameterModifier
    {
        /// <summary>
        /// 補正を識別する一意のIDを取得する。
        /// </summary>
        public Guid Id { get; }

        /// <summary>
        /// 補正方法を取得する。
        /// </summary>
        public ParameterModifierType Type { get; }

        /// <summary>
        /// 補正値を取得する。
        /// 加算補正の場合は加算量、
        /// 乗算補正の場合は倍率を表す。
        /// </summary>
        public float Value { get; }

        /// <summary>
        /// 補正の発生元となるオブジェクトを取得する。
        /// </summary>
        /// <remarks>
        /// 発生元を指定しない場合はnullとなる。
        /// 発生元の生存期間は管理しない。
        /// </remarks>
        public object Source { get; }

        /// <summary>
        /// パラメーター値に影響しない補正かどうかを取得する。
        /// </summary>
        public bool IsNeutral
        {
            get
            {
                if (Type == ParameterModifierType.Additive)
                {
                    return Value == 0f;
                }

                return Value == 1f;
            }
        }

        /// <summary>
        /// パラメーターの補正情報を生成する。
        /// </summary>
        /// <param name="type">補正方法</param>
        /// <param name="value">加算量または乗算倍率</param>
        /// <param name="source">補正の発生元。省略可能</param>
        /// <exception cref="ArgumentOutOfRangeException">
        /// 未対応の補正方法、不正な数値、
        /// または負数の乗算倍率が指定された場合に発生する。
        /// </exception>
        public ParameterModifier(
            ParameterModifierType type,
            float value,
            object source = null)
        {
            // 対応している補正方法か確認する。
            if (type != ParameterModifierType.Additive &&
                type != ParameterModifierType.Multiplicative)
            {
                throw new ArgumentOutOfRangeException(
                    nameof(type),
                    "未対応の補正方法です。");
            }

            // 補正値が有限値であることを確認する。
            if (float.IsNaN(value) || float.IsInfinity(value))
            {
                throw new ArgumentOutOfRangeException(
                    nameof(value),
                    "補正値には有限値を指定してください。");
            }

            // 乗算補正による符号の反転を禁止する。
            if (type == ParameterModifierType.Multiplicative &&
                value < 0f)
            {
                throw new ArgumentOutOfRangeException(
                    nameof(value),
                    "乗算倍率は0以上である必要があります。");
            }

            // 補正ごとに独立した識別子を生成する。
            Id = Guid.NewGuid();

            Type = type;
            Value = value;
            Source = source;
        }

        /// <summary>
        /// 加算補正を生成する。
        /// </summary>
        /// <param name="value">加算量。負数の場合は減算</param>
        /// <param name="source">補正の発生元。省略可能</param>
        /// <returns>生成された加算補正</returns>
        /// <exception cref="ArgumentOutOfRangeException">
        /// 補正値が有限値ではない場合に発生する。
        /// </exception>
        public static ParameterModifier CreateAdditive(
            float value,
            object source = null)
        {
            return new ParameterModifier(
                ParameterModifierType.Additive,
                value,
                source);
        }

        /// <summary>
        /// 乗算補正を生成する。
        /// </summary>
        /// <param name="multiplier">0以上の乗算倍率</param>
        /// <param name="source">補正の発生元。省略可能</param>
        /// <returns>生成された乗算補正</returns>
        /// <exception cref="ArgumentOutOfRangeException">
        /// 倍率が有限値ではない場合、
        /// または負数の場合に発生する。
        /// </exception>
        public static ParameterModifier CreateMultiplicative(
            float multiplier,
            object source = null)
        {
            return new ParameterModifier(
                ParameterModifierType.Multiplicative,
                multiplier,
                source);
        }

        /// <summary>
        /// 指定された識別子と自身の識別子が一致するか判定する。
        /// </summary>
        /// <param name="id">比較対象の補正ID</param>
        /// <returns>識別子が一致する場合はtrue</returns>
        public bool MatchesId(Guid id)
        {
            return Id == id;
        }

        /// <summary>
        /// 指定されたオブジェクトが補正の発生元か判定する。
        /// </summary>
        /// <param name="source">比較対象のオブジェクト</param>
        /// <returns>同一の発生元である場合はtrue</returns>
        /// <remarks>
        /// 値の等価性ではなく参照の一致によって判定する。
        /// nullは有効な発生元として扱わない。
        /// </remarks>
        public bool IsFromSource(object source)
        {
            return source != null &&
                   ReferenceEquals(Source, source);
        }

        /// <summary>
        /// 補正情報を確認用の文字列に変換する。
        /// </summary>
        /// <returns>補正方法、補正値、識別子を含む文字列</returns>
        public override string ToString()
        {
            return $"{Type}: {Value} (ID: {Id})";
        }
    }
}
